from manim import *

# Manimator draws text with Crimson Pro, a free font (fonts.google.com). Without it installed,
# Manim uses its default font instead.
Text.set_default(font="Crimson Pro")


class Intro(Scene):
    def construct(self):
        # Objects
        title = Text("Made with Manimator", font_size=48)
        title.set_color(WHITE)
        title.move_to([0, 3, 0])
        circle = Circle(radius=1)
        circle.set_stroke(RED)
        circle.set_fill(RED, opacity=0.5)
        circle.move_to([-3.5, 0, 0])
        square = Square(side_length=2)
        square.set_stroke(BLUE)
        square.set_fill(BLUE, opacity=0.5)
        square.move_to([0, 0, 0])
        square.rotate(45 * DEGREES)
        triangle = Triangle()
        triangle.set_stroke(YELLOW)
        triangle.set_fill(YELLOW, opacity=0.5)
        triangle.move_to([3.5, 0, 0])
        triangle.scale(1.3)
        eq = MathTex(r"e^{i\pi} + 1 = 0", font_size=48)
        eq.set_color(WHITE)
        eq.move_to([0, -2.6, 0])
        box = SurroundingRectangle(eq)
        box.set_stroke(YELLOW)
        box.set_fill(YELLOW)
        star = Star(n=5, outer_radius=1, inner_radius=0.4)
        star.set_stroke(GOLD)
        star.set_fill(GOLD, opacity=0.8)
        star.move_to([3.5, 0, 0])

        # Animation
        self.play(Write(title), run_time=1)
        self.play(
            LaggedStart(DrawBorderThenFill(circle), DrawBorderThenFill(square), DrawBorderThenFill(triangle), lag_ratio=0.3),
            run_time=2,
        )
        self.play(square.animate.rotate(180 * DEGREES), Indicate(circle), run_time=1)
        self.play(FadeIn(eq, shift=UP), run_time=1)
        self.play(Create(box), run_time=1)
        self.wait(1)
        self.play(
            ReplacementTransform(triangle, star),
            run_time=1,
            rate_func=rate_functions.ease_in_out_sine,
        )


class Plotting(Scene):
    def construct(self):
        # Objects
        axes = Axes(x_range=[-5, 5, 1], y_range=[-3, 3, 1], x_length=10, y_length=6, axis_config={"include_numbers": True})
        axes.move_to([0, 0, 0])
        dot = Dot(radius=0.1)
        dot.set_stroke(WHITE)
        dot.set_fill(PURE_YELLOW)
        dot.move_to([-4, -2, 0])

        # Animation
        self.play(Create(axes), run_time=1)
        self.play(GrowFromCenter(dot), run_time=1)
        self.play(
            dot.animate.shift(8 * RIGHT + 4 * UP),
            Flash(dot, flash_radius=0.5),
            run_time=2,
        )
